local Players = game:GetService("Players") local RunService = game:GetService("RunService") local UserInputService = game:GetService("UserInputService") local LocalPlayer = Players.LocalPlayer local PlayerGui = LocalPlayer:WaitForChild("PlayerGui") local Camera = workspace.CurrentCamera print("▶ PC/모바일 포커스 우회 및 무기 장착 패치 적용...") -- 1. PC 마우스 잠금 및 모달(Modal) 상태 해제 (포커스 꼬임 방지) UserInputService.ModalEnabled = false UserInputService.MouseBehavior = Enum.MouseBehavior.Default -- 2. 로비 UI 숨기기 local function hideLobbyUI() for _, gui in ipairs(PlayerGui:GetDescendants()) do if gui:IsA("ScreenGui") or gui:IsA("Frame") then if gui.Name == "Menu" or gui.Name == "HUD" or gui.Name == "Container" or gui.Name:lower():find("tycoon") then pcall(function() if gui:FindFirstChild("Quick Play") or gui:FindFirstChild("빠른플레이") or gui:FindFirstChild("기지 선택") or gui.Name == "Menu" then gui.Visible = false end end) end end end pcall(function() local mainUI = PlayerGui:FindFirstChild("UI", true) if mainUI and mainUI:FindFirstChild("Container") then local menu = mainUI.Container:FindFirstChild("Menu") if menu then menu.Visible = false end end end) end -- 3. 최초 1회 카메라 포커스 정상화 (ACS_Client 로직 연동) local function setNormalCamera(humanoid) if humanoid then Camera.CameraType = Enum.CameraType.Custom Camera.CameraSubject = humanoid Camera.FieldOfView = 70 LocalPlayer.CameraMode = Enum.CameraMode.Classic end end -- 캐릭터 첫 접속 시 카메라 복구 if LocalPlayer.Character and LocalPlayer.Character:FindFirstChild("Humanoid") then setNormalCamera(LocalPlayer.Character.Humanoid) end -- 4. 메인 루프 (앵커 해제, 무기 장착, UI 숨김) RunService.RenderStepped:Connect(function() local character = LocalPlayer.Character if not character then return end -- 캐릭터 앵커 해제 local rootPart = character:FindFirstChild("HumanoidRootPart") if rootPart and rootPart.Anchored then rootPart.Anchored = false end local humanoid = character:FindFirstChildOfClass("Humanoid") if not humanoid or humanoid.Health <= 0 then return end -- 카메라 타입이 Scriptable로 고정되어 있으면 Custom으로 복원 if Camera.CameraType == Enum.CameraType.Scriptable then Camera.CameraType = Enum.CameraType.Custom Camera.CameraSubject = humanoid end -- 백팩 내 무기 강제 장착 if not character:FindFirstChildOfClass("Tool") then for _, tool in ipairs(LocalPlayer.Backpack:GetChildren()) do if tool:IsA("Tool") then pcall(function() humanoid:EquipTool(tool) end) end end end hideLobbyUI() end) -- 캐릭터 리스폰 대응 LocalPlayer.CharacterAdded:Connect(function(newChar) local humanoid = newChar:WaitForChild("Humanoid") task.wait(0.3) setNormalCamera(humanoid) end) print("▶ 패치 완료! PC에서도 모바일과 동일하게 동작합니다.")
